-- 097_project_cost_closeout.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.project_cost_closeout_versions(
 id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),status text NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),approved_budget numeric(24,2)NOT NULL CHECK(approved_budget>=0),award_value numeric(24,2)NOT NULL CHECK(award_value>=0),approved_variations numeric(24,2)NOT NULL CHECK(approved_variations>=0),latest_forecast numeric(24,2),final_cost numeric(24,2)NOT NULL CHECK(final_cost>=0),variance_to_budget numeric(24,2)NOT NULL,variance_to_award numeric(24,2)NOT NULL,variance_to_forecast numeric(24,2),budget_variance_explanation text NOT NULL CHECK(btrim(budget_variance_explanation)<>''AND char_length(budget_variance_explanation)<=3000),award_variance_explanation text NOT NULL CHECK(btrim(award_variance_explanation)<>''AND char_length(award_variance_explanation)<=3000),forecast_variance_explanation text NOT NULL CHECK(btrim(forecast_variance_explanation)<>''AND char_length(forecast_variance_explanation)<=3000),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version_number)
);CREATE UNIQUE INDEX IF NOT EXISTS project_cost_closeout_one_confirmed_idx ON public.project_cost_closeout_versions(project_id)WHERE status='CONFIRMED';
CREATE OR REPLACE FUNCTION private.prevent_cost_closeout_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PROJECT_COST_CLOSEOUT_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS project_cost_closeout_immutable ON public.project_cost_closeout_versions;CREATE TRIGGER project_cost_closeout_immutable BEFORE UPDATE OR DELETE ON public.project_cost_closeout_versions FOR EACH ROW EXECUTE FUNCTION private.prevent_cost_closeout_mutation();
ALTER TABLE public.project_cost_closeout_versions ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS project_cost_closeout_select ON public.project_cost_closeout_versions;CREATE POLICY project_cost_closeout_select ON public.project_cost_closeout_versions FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_cost_closeout_versions FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_cost_closeout_versions TO authenticated;
CREATE OR REPLACE FUNCTION public.save_project_cost_closeout(p_project_id bigint,p_closeout_id uuid,p_final_cost numeric,p_budget_explanation text,p_award_explanation text,p_forecast_explanation text,p_confirm boolean,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;req public.write_command_requests%ROWTYPE;version_no integer;budget numeric;award numeric;variations numeric;forecast numeric;currency text;state text;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_COST_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_closeout_id IS NULL OR p_client_request_id IS NULL OR COALESCE(p_final_cost,-1)<0 OR btrim(COALESCE(p_budget_explanation,''))=''OR btrim(COALESCE(p_award_explanation,''))=''OR btrim(COALESCE(p_forecast_explanation,''))=''OR char_length(p_budget_explanation)>3000 OR char_length(p_award_explanation)>3000 OR char_length(p_forecast_explanation)>3000 THEN RAISE EXCEPTION'INVALID_PROJECT_COST_CLOSEOUT'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.cost.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.cost.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_cost_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')THEN RAISE EXCEPTION'PROJECT_COST_CLOSEOUT_ALREADY_CONFIRMED'USING ERRCODE='55000';END IF;SELECT total_amount,currency_code INTO budget,currency FROM public.approved_budget_baselines WHERE project_id=p_project_id;SELECT contract_value,COALESCE(currency,currency_code)INTO award,currency FROM public.project_tender_awards WHERE project_id=p_project_id;IF budget IS NULL OR award IS NULL OR currency IS NULL THEN RAISE EXCEPTION'COST_CLOSEOUT_REQUIRES_APPROVED_BUDGET_AND_AWARD'USING ERRCODE='55000';END IF;SELECT COALESCE(sum(approved_amount),0)INTO variations FROM public.project_variations WHERE project_id=p_project_id AND status='APPROVED';SELECT forecast_final_cost INTO forecast FROM public.project_cost_forecast_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;SELECT COALESCE(max(version_number),0)+1 INTO version_no FROM public.project_cost_closeout_versions WHERE project_id=p_project_id;state:=CASE WHEN COALESCE(p_confirm,false)THEN'CONFIRMED'ELSE'DRAFT'END;INSERT INTO public.project_cost_closeout_versions VALUES(p_closeout_id,p_project_id,version_no,state,currency,budget,award,variations,forecast,p_final_cost,p_final_cost-budget,p_final_cost-award,CASE WHEN forecast IS NULL THEN NULL ELSE p_final_cost-forecast END,btrim(p_budget_explanation),btrim(p_award_explanation),btrim(p_forecast_explanation),u,now());result:=jsonb_build_object('costCloseoutId',p_closeout_id,'versionNumber',version_no,'status',state,'currencyCode',currency,'approvedBudget',budget,'awardValue',award,'approvedVariations',variations,'latestForecast',forecast,'finalCost',p_final_cost,'varianceToBudget',p_final_cost-budget,'varianceToAward',p_final_cost-award,'varianceToForecast',CASE WHEN forecast IS NULL THEN NULL ELSE p_final_cost-forecast END);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_cost_closeout(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE x public.project_cost_closeout_versions%ROWTYPE;BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_COST_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT *INTO x FROM public.project_cost_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;RETURN jsonb_build_object('projectId',p_project_id,'hasCloseout',x.id IS NOT NULL,'closeout',CASE WHEN x.id IS NULL THEN NULL ELSE jsonb_build_object('costCloseoutId',x.id,'versionNumber',x.version_number,'status',x.status,'currencyCode',x.currency_code,'approvedBudget',x.approved_budget,'awardValue',x.award_value,'approvedVariations',x.approved_variations,'latestForecast',x.latest_forecast,'finalCost',x.final_cost,'varianceToBudget',x.variance_to_budget,'varianceToAward',x.variance_to_award,'varianceToForecast',x.variance_to_forecast,'budgetVarianceExplanation',x.budget_variance_explanation,'awardVarianceExplanation',x.award_variance_explanation,'forecastVarianceExplanation',x.forecast_variance_explanation,'createdAt',x.created_at)END);END;$$;
REVOKE ALL ON FUNCTION private.prevent_cost_closeout_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.save_project_cost_closeout(bigint,uuid,numeric,text,text,text,boolean,uuid),public.get_project_cost_closeout(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.save_project_cost_closeout(bigint,uuid,numeric,text,text,text,boolean,uuid),public.get_project_cost_closeout(bigint)TO authenticated;
COMMIT;
